"""dump_apply: writing dump_relocs' symbolic bodies back into a dump source."""
import sys
from pathlib import Path

import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
import dump_apply as A  # noqa: E402

SOURCE = """.386
.model flat
_TEXT SEGMENT

; ghidra: FUN_1  retail @ 0x00001000 size 6
public ?d_a@@YAXXZ
?d_a@@YAXXZ PROC
    db 0E8h, 00h, 00h, 00h, 00h, 0C3h
?d_a@@YAXXZ ENDP

; dead dump, no live row
public ?d_b@@YAXXZ
?d_b@@YAXXZ PROC
    db 0C3h
?d_b@@YAXXZ ENDP
_TEXT ENDS
END
"""

GENERATED = """.386
.model flat
; generated by tools/dump_relocs.py from x.asm; do not edit

EXTERN ?callee@@YAXXZ:NEAR
EXTERN ?d_b@@YAXXZ:NEAR
EXTERN g_00500000:BYTE

_TEXT$d00401000 SEGMENT BYTE PUBLIC FLAT 'CODE'
; retail VA 0x00401000 size 6
public ?d_a@@YAXXZ
?d_a@@YAXXZ PROC
    call ?callee@@YAXXZ
    dd g_00500000 + 04h
    jmp ?d_b@@YAXXZ
?d_a@@YAXXZ ENDP
_TEXT$d00401000 ENDS

END
"""


def test_converted_proc_gets_its_own_segment_and_only_needed_externs():
    blocks, externs = A.generated_blocks(GENERATED)
    assert set(blocks) == {"?d_a@@YAXXZ"}
    out = A.rewrite(SOURCE, ["?d_a@@YAXXZ"], blocks, externs).split("\n")
    assert out[2] == A.HEADER
    # ?d_b is defined in the source itself: no EXTERN (MASM would call it a redefinition)
    assert [x for x in out if x.startswith("EXTERN")] == ["EXTERN ?callee@@YAXXZ:NEAR", "EXTERN g_00500000:BYTE"]
    i = out.index("_TEXT ENDS")
    assert out[i + 1].startswith("_TEXT$d00401000 SEGMENT") and out[i + 1:].index("_TEXT SEGMENT") > 0
    assert "    db 0E8h, 00h, 00h, 00h, 00h, 0C3h" not in out          # raw retail bytes gone
    assert "?d_b@@YAXXZ PROC" in out and "    db 0C3h" in out             # dead PROC untouched


def test_unknown_proc_is_refused():
    blocks, externs = A.generated_blocks(GENERATED.replace("?d_a@@", "?d_z@@"))
    with pytest.raises(ValueError):
        A.rewrite(SOURCE, ["?d_z@@YAXXZ"], blocks, externs)


def test_referenced_reads_addends():
    assert A.referenced(["    dd g_1 + 04h", "    call ?f@@YAXXZ", "    jne x - 010h", "    db 0C3h"]) == \
        {"g_1", "?f@@YAXXZ", "x"}
